using System;
using UnityEngine;

namespace TheLastFortress
{
    /// <summary>
    /// Asset references the bootstrap needs. Generated by the editor setup scripts. A content asset with
    /// <see cref="releaseDefinitions"/> runs the plan 008 release (twelve nights, with the six-night MVP kept for legacy
    /// saves); with only <see cref="mvpDefinitions"/> it runs the six-night MVP; otherwise the one-wave prototype.
    /// </summary>
    [CreateAssetMenu(menuName = "The Last Fortress/Prototype Content", fileName = "PrototypeContent")]
    public sealed class PrototypeContent : ScriptableObject
    {
        public PrototypeDefinitionsAsset definitions;

        [Tooltip("When set, the scene runs the multi-night MVP with these definitions.")]
        public MvpDefinitionsAsset mvpDefinitions;

        [Tooltip("When set, the scene runs the release (twelve-night) profile; mvpDefinitions then serves legacy six-night saves.")]
        public ReleaseDefinitionsAsset releaseDefinitions;

        [Header("Entity prefabs")]
        public GameObject keepPrefab;
        public GameObject wallPrefab;
        public GameObject towerPrefab;
        public GameObject gruntPrefab;
        public GameObject housePrefab;
        public GameObject farmPrefab;
        public GameObject trapPrefab;
        public GameObject runnerPrefab;
        public GameObject brutePrefab;
        public GameObject golemPrefab;

        [Header("Release kinds (plan 008)")]
        public GameObject cannonPrefab;
        public GameObject watchtowerPrefab;
        public GameObject repairStationPrefab;
        public GameObject raiderArcherPrefab;
        public GameObject bomberPrefab;
        public GameObject commanderPrefab;

        [Tooltip("Plan 012 player hero (CharacterRig). Null shows a tinted Grunt rig as a placeholder.")]
        public GameObject heroPrefab;

        [Tooltip("Plan 019 release-rules-4 hero (HeroAnimationRig: elbows, wrists, ankles). Null falls back to the legacy hero.")]
        public GameObject contactHeroPrefab;

        [Tooltip("release-rules-4 1 x 1 Cannon (field gun on a timber turntable, no stone emplacement). Null draws the 2 x 2 model at half size.")]
        public GameObject compactCannonPrefab;

        [Tooltip("MVP connected Walls, indexed by WallShape (Isolated, End, Straight, Corner, T, Cross), canonical facing north. Empty keeps the prototype Wall.")]
        public GameObject[] wallShapePrefabs;

        [Tooltip("Uniform scale for enemy views (MVP readability at default zoom). 0 or 1 = prefab scale.")]
        public float enemyScale = 1f;

        /// <summary>Authored board look, lighting and post-processing (plan 011); null keeps the generated blockout look.</summary>
        public ArtDirection art;

        [Header("Materials")]
        public Material grass;
        public Material water;
        public Material timberShadow;
        public Material overlay;
        public Material arrow;
        public Material foliage;
        public Material rock;

        [Tooltip("Optional overlay material drawn on top of geometry (route, breach, selection). Falls back to 'overlay'.")]
        public Material overlayOnTop;

        [Tooltip("Spec 011: see-through material for meshes that hide the hero in the hero view (TheLastFortress/HeroFade).")]
        public Material heroFade;

        [Header("Presentation (MVP; optional — empty keeps the scene silent and the cards text-only)")]
        public AudioContent audio;

        [Tooltip("HUD card icons indexed by BuildingKind (Keep slot unused), white line art tinted by the HUD.")]
        public Texture2D[] buildingIcons;

        public Texture2D goldIcon;

        [Tooltip("Hardware cursor shown while dragging the map with the right mouse button (import type Cursor).")]
        public Texture2D panCursor;

        public Texture2D IconFor(BuildingKind kind) =>
            buildingIcons != null && (int)kind < buildingIcons.Length ? buildingIcons[(int)kind] : null;

        [Header("Layouts")]
        public TextAsset winningLayout;
        public TextAsset losingLayout;
        public TextAsset stressLayout;

        public bool IsMvp => mvpDefinitions != null || releaseDefinitions != null;
        public bool IsRelease => releaseDefinitions != null;

        /// <summary>Explicit per enemy kind; a missing prefab is a setup error, never a Grunt stand-in.</summary>
        public GameObject EnemyPrefabFor(EnemyKind kind)
        {
            GameObject prefab;
            switch (kind)
            {
                case EnemyKind.Grunt: prefab = gruntPrefab; break;
                case EnemyKind.Runner: prefab = runnerPrefab; break;
                case EnemyKind.Brute: prefab = brutePrefab; break;
                case EnemyKind.SiegeGolem: prefab = golemPrefab; break;
                case EnemyKind.Archer: prefab = raiderArcherPrefab; break;
                case EnemyKind.Bomber: prefab = bomberPrefab; break;
                case EnemyKind.SiegeCommander: prefab = commanderPrefab; break;
                default: throw new ArgumentOutOfRangeException(nameof(kind), kind, null);
            }

            if (prefab == null) throw new InvalidOperationException($"No prefab assigned for {kind} in {name}; run the setup menu.");
            return prefab;
        }

        /// <summary>
        /// The model for this run's definition: a 1 x 1 (release-rules-4) Cannon uses <see cref="compactCannonPrefab"/> when it
        /// is assigned; everything else as <see cref="PrefabFor(BuildingKind)"/>.
        /// </summary>
        public GameObject PrefabFor(BuildingDefinition def) => CompactCannon(def) ? compactCannonPrefab : PrefabFor(def.Kind);

        public bool CompactCannon(BuildingDefinition def) =>
            def != null && def.Kind == BuildingKind.Cannon && def.FootprintSize == 1 && compactCannonPrefab != null;

        /// <summary>Explicit per kind; a missing prefab is a setup error, never a silent substitute.</summary>
        public GameObject PrefabFor(BuildingKind kind)
        {
            GameObject prefab;
            switch (kind)
            {
                case BuildingKind.Keep: prefab = keepPrefab; break;
                case BuildingKind.Wall: prefab = wallPrefab; break;
                case BuildingKind.Tower: prefab = towerPrefab; break;
                case BuildingKind.House: prefab = housePrefab; break;
                case BuildingKind.Farm: prefab = farmPrefab; break;
                case BuildingKind.SpikeTrap: prefab = trapPrefab; break;
                case BuildingKind.Cannon: prefab = cannonPrefab; break;
                case BuildingKind.Watchtower: prefab = watchtowerPrefab; break;
                case BuildingKind.RepairStation: prefab = repairStationPrefab; break;
                default: throw new ArgumentOutOfRangeException(nameof(kind), kind, null);
            }

            if (prefab == null) throw new InvalidOperationException($"No prefab assigned for {kind} in {name}; run the setup menu.");
            return prefab;
        }
    }
}
